// Paints one frame of the review into Raster cells: `[codePoint, fg, bg]` u32 triplets, row-major. Pure and
// synchronous: the caller loads the chunks the window needs first, so a frame costs only the cells it fills.

import { Kind, type Highlights, type Lines, type Manifest, spanCol, spanLen, spanStyle } from './chunks';
import { DEFAULT, styleFg, theme } from './theme';
import type { View } from './view';

export type Loaded = { lines: Lines; hl?: Highlights };

export type Source = {
  view: View;
  /** The cursor's row, highlighted. */
  cursor: number;
  /** How many files are marked viewed; the marks themselves are the view's collapsed files. */
  viewed?: { count: number };
  /** Global lines carrying a comment, marked in the gutter, and how many comments are waiting to be sent. */
  comments?: { lines: ReadonlySet<number>; count: number };
  /** A chunk already in memory, or undefined while it is not (drawn as a placeholder, never awaited). */
  chunk(index: number): Loaded | undefined;
};

/** Columns before the code: a 6-digit line number, a space, the sign, a space. */
export const GUTTER = 9;
const SPACE = 0x20;

class Canvas {
  constructor(
    readonly cells: Uint32Array,
    readonly cols: number,
  ) {}

  fill(row: number, fg: number, bg: number) {
    const cells = this.cells;
    let i = row * this.cols * 3;
    const end = i + this.cols * 3;
    for (; i < end; i += 3) {
      cells[i] = SPACE;
      cells[i + 1] = fg;
      cells[i + 2] = bg;
    }
  }

  /** Writes code points from `units[start, end)` at `col`, clipped to the row; returns the column after. */
  units(row: number, col: number, units: Uint16Array, start: number, end: number, fg: number): number {
    const cells = this.cells;
    const stop = Math.min(end, start + this.cols - col);
    let i = (row * this.cols + col) * 3;
    for (let u = start; u < stop; u++, i += 3) {
      cells[i] = units[u]!;
      cells[i + 1] = fg;
    }
    return col + Math.max(0, stop - start);
  }

  text(row: number, col: number, s: string, fg: number): number {
    const cells = this.cells;
    const stop = Math.min(s.length, this.cols - col);
    let i = (row * this.cols + col) * 3;
    for (let k = 0; k < stop; k++, i += 3) {
      cells[i] = s.charCodeAt(k);
      cells[i + 1] = fg;
    }
    return col + Math.max(0, stop);
  }

  /** A line number right-aligned in 6 columns, no string made. */
  number(row: number, n: number, fg: number) {
    const cells = this.cells;
    let col = 5;
    do {
      if (col < this.cols) {
        const i = (row * this.cols + col) * 3;
        cells[i] = 0x30 + (n % 10);
        cells[i + 1] = fg;
      }
      n = Math.floor(n / 10);
      col--;
    } while (n > 0 && col >= 0);
  }

  background(row: number, bg: number) {
    const cells = this.cells;
    const end = (row + 1) * this.cols * 3;
    for (let i = row * this.cols * 3 + 2; i < end; i += 3) cells[i] = bg;
  }

  recolor(row: number, from: number, to: number, fg: number) {
    const cells = this.cells;
    const stop = Math.min(to, this.cols);
    for (let col = from, i = (row * this.cols + from) * 3 + 1; col < stop; col++, i += 3) cells[i] = fg;
  }
}

/** The header bar's text: the cursor's file and where the cursor is. */
export function title(src: Pick<Source, 'view' | 'cursor' | 'viewed' | 'comments'>): string {
  const { view, cursor, viewed, comments } = src;
  const { manifest } = view;
  if (manifest.files === 0) return ` ${manifest.headName} ← ${manifest.baseName} │ no changes`;
  const index = view.fileOfRow(cursor);
  const file = manifest.file(index);
  const at = view.rows > 0 ? Math.floor(((cursor + 1) / view.rows) * 100) : 100;
  const mark = view.collapsed[index] === 1 ? '✓ ' : '';
  const count = viewed === undefined ? '' : ` │ ✓ ${viewed.count}/${manifest.files} viewed`;
  const drafts = comments === undefined || comments.count === 0 ? '' : ` │ ✎ ${comments.count}`;
  return ` ${manifest.headName} ← ${manifest.baseName} │ ${index + 1}/${manifest.files} ${mark}${file.path} +${file.added} −${file.removed} │ ${at}%${count}${drafts}`;
}

/**
 * Fills `cells` (cols × rows triplets) with the bar on row 0 and the view from row `top` below it. Returns how many
 * rows were drawn as placeholders because their chunk was not loaded.
 */
export function paint(cells: Uint32Array, cols: number, rows: number, top: number, src: Source): number {
  const canvas = new Canvas(cells, cols);
  const { view } = src;
  canvas.fill(0, theme.barFg, theme.barBg);
  canvas.text(0, 0, title(src), theme.barFg);

  let missing = 0;
  for (let row = 1; row < rows; row++) {
    const at = top + row - 1;
    if (at >= view.rows) {
      canvas.fill(row, DEFAULT, DEFAULT);
      continue;
    }
    const { file, line, note } = view.locate(at);
    if (note > 0) drawNote(canvas, row, view.notes.get(line)?.[note - 1] ?? '', note === 1);
    else {
      const markCol = drawRow(canvas, row, file, line, src);
      if (markCol < 0) missing++;
      else if (src.comments?.lines.has(line)) canvas.text(row, markCol, '●', theme.commentFg);
    }
    if (at === src.cursor) canvas.background(row, theme.cursorBg);
  }
  return missing;
}

/** A row's comment mark goes in the gutter's free column; a file header's in place of its glyph. */
const MARK = 6;
const HEADER_MARK = 1;

/** Columns of a note row before its text: the gutter, then the pen on its first row. */
export const NOTE_TEXT = GUTTER + 2;

/** One row of a note (a comment) under its line: a pen on the first row, the text in the comment colour. */
function drawNote(canvas: Canvas, row: number, text: string, isFirst: boolean) {
  canvas.fill(row, theme.commentFg, theme.noteBg);
  if (isFirst) canvas.text(row, GUTTER, '✎', theme.commentFg);
  canvas.text(row, NOTE_TEXT, text, theme.noteFg);
}

/**
 * Draws `line` of `file` on canvas row `row`. Returns the column a comment mark goes in, or -1 for a placeholder drawn
 * because the line's chunk is not loaded.
 */
function drawRow(canvas: Canvas, row: number, file: number, line: number, src: Source): number {
  const { view } = src;
  const { manifest } = view;
  if (view.collapsed[file] === 1) {
    const info = manifest.file(file);
    canvas.fill(row, theme.dimFg, theme.viewedBg);
    canvas.text(row, 0, ' ✓', theme.viewedFg);
    const col = canvas.text(row, 3, info.path, theme.dimFg);
    canvas.text(row, col, `  +${info.added} −${info.removed}`, theme.gutterFg);
    return HEADER_MARK;
  }
  const chunk = src.chunk(Math.floor(line / manifest.chunkLines));
  if (chunk === undefined) {
    canvas.fill(row, DEFAULT, DEFAULT);
    canvas.text(row, GUTTER, '…', theme.dimFg);
    return -1;
  }
  const i = line % manifest.chunkLines;
  const { lines, hl } = chunk;
  const kind = lines.kind[i]!;
  const start = lines.start[i]!;
  const end = lines.start[i + 1]!;

  switch (kind) {
    case Kind.File:
      canvas.fill(row, theme.fileFg, theme.fileBg);
      canvas.text(row, 0, ' ▍', theme.hunkFg);
      canvas.units(row, 3, lines.text, start, end, theme.fileFg);
      return HEADER_MARK;
    case Kind.Hunk:
      canvas.fill(row, DEFAULT, DEFAULT);
      canvas.units(row, 2, lines.text, start, end, theme.hunkFg);
      return MARK;
    case Kind.Note:
      canvas.fill(row, DEFAULT, DEFAULT);
      canvas.units(row, GUTTER, lines.text, start, end, theme.dimFg);
      return MARK;
  }

  const isAdd = kind === Kind.Add;
  const isDel = kind === Kind.Del;
  canvas.fill(row, DEFAULT, isAdd ? theme.addBg : isDel ? theme.delBg : DEFAULT);
  canvas.number(row, isDel ? lines.oldNo[i]! : lines.newNo[i]!, theme.gutterFg);
  if (isAdd) canvas.text(row, 7, '+', theme.addSign);
  else if (isDel) canvas.text(row, 7, '-', theme.delSign);
  canvas.units(row, GUTTER, lines.text, start, end, DEFAULT);

  if (hl !== undefined) {
    for (let s = hl.start[i]!, last = hl.start[i + 1]!; s < last; s++) {
      const span = hl.spans[s]!;
      const fg = styleFg[spanStyle(span)] ?? DEFAULT;
      if (fg === DEFAULT) continue;
      const col = GUTTER + spanCol(span);
      canvas.recolor(row, col, col + spanLen(span), fg);
    }
  }
  return MARK;
}

files.hooks/view.ts:
// The pane's rows over the review's global lines. A collapsed file shows only its header row, and a line with notes
// (comments) is followed by a row per line of note text, so the rows the pane scrolls through are not the lines: `top`
// and the cursor count rows, and this maps a row to its file, line and note row.

import type { Manifest } from './chunks';

export class View {
  /** The row each file's header is on; one more entry holds the row count. */
  private readonly rowStart: Uint32Array;
  /** Per file with notes on lines it shows: `[local line, rows, ...]` in line order. */
  private notesByFile = new Map<number, number[]>();
  /** What `locate` found, reused so a frame allocates nothing. */
  readonly at = { file: 0, line: 0, note: 0 };

  constructor(
    readonly manifest: Manifest,
    /** 1 per file index shown as its header alone. Shared with the caller: `rebuild()` after changing it. */
    readonly collapsed: Uint8Array,
    /** The rows of text drawn under a global line, by line. */
    public notes: ReadonlyMap<number, readonly string[]> = new Map(),
  ) {
    this.rowStart = new Uint32Array(manifest.files + 1);
    this.rebuild();
  }

  rebuild() {
    const { manifest, collapsed, rowStart } = this;
    const byFile = new Map<number, number[]>();
    for (const [line, rows] of this.notes) {
      if (rows.length === 0 || line >= manifest.totalLines) continue;
      const file = manifest.fileAt(line);
      const local = line - manifest.firstLine(file);
      if (local >= this.shown(file)) continue;
      const list = byFile.get(file) ?? [];
      list.push(local, rows.length);
      byFile.set(file, list);
    }
    for (const list of byFile.values()) {
      const pairs: [number, number][] = [];
      for (let k = 0; k < list.length; k += 2) pairs.push([list[k]!, list[k + 1]!]);
      pairs.sort((a, b) => a[0] - b[0]);
      list.length = 0;
      for (const [local, rows] of pairs) list.push(local, rows);
    }
    this.notesByFile = byFile;
    let row = 0;
    for (let i = 0; i < manifest.files; i++) {
      rowStart[i] = row;
      row += this.shown(i);
      const list = byFile.get(i);
      if (list !== undefined) for (let k = 1; k < list.length; k += 2) row += list[k]!;
    }
    rowStart[manifest.files] = row;
  }

  /** Lines a file shows: its header alone when collapsed. */
  private shown(file: number): number {
    return this.collapsed[file] === 1 ? 1 : this.manifest.lineCount(file);
  }

  get rows(): number {
    return this.rowStart[this.manifest.files]!;
  }

  headerRow(file: number): number {
    return this.rowStart[file]!;
  }

  /** The file a row belongs to: binary search over the files' header rows. */
  fileOfRow(row: number): number {
    let lo = 0;
    let hi = this.manifest.files - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >>> 1;
      if (this.rowStart[mid]! <= row) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  /** A row's file, global line, and note row: 0 for the line itself, 1 and on for the rows of its notes. */
  locate(row: number): View['at'] {
    const file = this.fileOfRow(row);
    const first = this.manifest.firstLine(file);
    let offset = row - this.rowStart[file]!;
    const at = this.at;
    at.file = file;
    at.note = 0;
    const list = this.notesByFile.get(file);
    if (list !== undefined) {
      for (let k = 0; k < list.length; k += 2) {
        const local = list[k]!;
        if (offset <= local) break;
        if (offset <= local + list[k + 1]!) {
          at.line = first + local;
          at.note = offset - local;
          return at;
        }
        offset -= list[k + 1]!;
      }
    }
    at.line = first + offset;
    return at;
  }

  /** The global line a row shows, or whose notes it shows; a collapsed file's header row is its header line. */
  lineOfRow(row: number): number {
    return this.locate(row).line;
  }

  /** The row a global line is on; a line inside a collapsed file is on its header row. */
  rowOfLine(line: number): number {
    const file = this.manifest.fileAt(line);
    const local = this.collapsed[file] === 1 ? 0 : line - this.manifest.firstLine(file);
    let row = this.rowStart[file]! + local;
    const list = this.notesByFile.get(file);
    if (list !== undefined) for (let k = 0; k < list.length && list[k]! < local; k += 2) row += list[k + 1]!;
    return row;
  }
